INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t2-p1', 'lt-t2', 1, 'You will hear a woman phoning a cycle tour company to book a tour for her colleagues.', 'Agent: Good afternoon, Greenway Cycle Tours, Paul speaking. How can I help? Woman: Hello. I''m interested in one of your guided tours for a group from my office. Agent: Lovely. How many people would it be? Woman: There are twelve of us. Well, it was going to be twelve, but two people have dropped out, so ten. Agent: Ten, fine. And which tour were you thinking of? We have the river tour, the castle tour and the vineyard tour. Woman: The castle one sounds interesting, but some of my colleagues aren''t very fit, and I''ve heard it''s quite hilly. Agent: It is. The river tour is completely flat. Woman: Then the river tour, please. Agent: When would you like to go? Woman: We were thinking of a Friday in June. Agent: Let me check. The sixth is full, but the thirteenth is free. Woman: The thirteenth is perfect. Agent: The tour starts at ten, and it''s about thirty kilometres in total, with a stop for lunch at a pub by the water. Woman: And what does it cost? Agent: It''s forty-five pounds per person, which includes the bike and a helmet. Lunch is extra. Woman: OK. Do people need to bring anything? Agent: Just comfortable shoes and a waterproof jacket. We supply water bottles. Woman: Where do we meet? Agent: At our shop, which is on Mill Lane, opposite the station. Woman: Great. And could I have a contact number for the guide on the day? Agent: The guide will be Karen, and I''ll text you her number the day before. Can I take your name? Woman: It''s Susan Ashworth. A, S, H, W, O, R, T, H. Agent: Thank you, Ms Ashworth. I''ll send you a confirmation email.', 30) ON CONFLICT (id) DO NOTHING;
