INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t3-p1', 'lt-t3', 1, 'You will hear a man phoning a festival office to volunteer.', 'Coordinator: Hello, Brookfield Summer Festival volunteers'' office. Man: Hi, I saw your advert for volunteers and I''d like to sign up. Coordinator: Great. Let me take some details. What''s your full name? Man: Daniel Okafor. That''s O, K, A, F, O, R. Coordinator: Thanks. And how old are you, Daniel? We need volunteers to be over eighteen. Man: I''m twenty-three. Coordinator: Lovely. What''s your address? Man: Flat 4, 27 Seaton Road. Coordinator: And which area would you like to work in? We need people for car parking, the information tent and litter collection. Man: I''d prefer the information tent. I''m good with people. Coordinator: Perfect. The festival runs from Thursday to Sunday. Which days can you do? Man: I work on Thursdays, so Friday to Sunday. Coordinator: That''s fine. Shifts are six hours long. Have you volunteered before? Man: Yes, I helped at a marathon last year. Coordinator: Excellent. All volunteers get a free T-shirt. What size are you? Man: Large, please. Coordinator: And do you have any dietary requirements? We provide meals for volunteers. Man: I''m vegetarian. Coordinator: Noted. Finally, you''ll need to attend a training session. There''s one on the twelfth of July and another on the nineteenth. Man: The twelfth is better for me. Coordinator: Great. It''s at the town hall at seven in the evening.', 30) ON CONFLICT (id) DO NOTHING;
