INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t3-p3', 'lt-t3', 3, 'You will hear two students, Hannah and Marcus, discussing a report on their museum work placement.', 'Hannah: Hi Marcus. Have you got a minute to talk about our museum placement report? Marcus: Sure. How did you find the placement overall? Hannah: I really enjoyed it. I thought I''d spend most of my time in the archives, but actually I was mainly working with visitors, which I preferred. Marcus: Same for me. The thing that surprised me most was how few staff there are. The museum relies on just six full-time employees. Hannah: I know. And the director told me their biggest challenge isn''t money, it''s attracting teenagers, who hardly ever visit. Marcus: That''s what our report should focus on, then. What did you think of the new digital guide? Hannah: The technology was impressive, but visitors found the headphones uncomfortable, so a lot of them gave up after ten minutes. Marcus: That''s a good point to include. Now, our tutor wants the report by the end of the month. Should we aim for five thousand words? Hannah: She said four thousand is the minimum, so let''s aim for about four and a half thousand. Marcus: OK. Let''s divide up the work. Who''s going to write the introduction? Hannah: I''ll do that, since I''ve already drafted some notes. Marcus: Fine. I''ll collect the visitor statistics; I''ve got the contact at the museum. Hannah: What about the interviews with staff? There are quite a lot. Marcus: Let''s share those; you take the curators and I''ll take the education team. Hannah: Good. And the recommendations? Marcus: You''re better at that kind of thing. You write them and I''ll check them. Hannah: OK. Then the photographs. Marcus: I took most of them, so I''ll choose which ones to use.', 30) ON CONFLICT (id) DO NOTHING;
