INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t4-p1', 'lt-t4', 1, 'You will hear a woman phoning a pet care service to arrange for someone to look after her cat.', 'Assistant: Happy Paws Pet Care, this is Tom. Woman: Hello, I''m going away next month and I need someone to look after my cat. Assistant: Of course. Can I start with your name? Woman: Yes, it''s Rachel Lindqvist. That''s L, I, N, D, Q, V, I, S, T. Assistant: Thank you. And your address? Woman: 15 Orchard Close, in Fenwick. Assistant: Great, that''s within our area. What''s your cat''s name? Woman: She''s called Pepper. Assistant: How old is she? Woman: She''s nine. Actually, no, she had her birthday in May, so she''s ten now. Assistant: Ten. And the dates you need? Woman: From the third to the seventeenth of August. Assistant: Two weeks. We usually visit twice a day. Would that suit you? Woman: She''s quite independent, so once a day would be enough. Assistant: Once a day, then, in the morning or the evening? Woman: The evening, please. That''s when she eats. Assistant: Does she need any medicine? Woman: Yes, she takes a tablet for her heart, crushed into her food. Assistant: I''ll make a note. Any other instructions? Woman: Please could you water my plants as well? Assistant: Certainly, there''s no extra charge for that. How would you like to leave the key? Woman: I''ll leave it with my neighbour at number 17. Assistant: Perfect. Our rate is twelve pounds per visit. Woman: That''s fine.', 30) ON CONFLICT (id) DO NOTHING;
