INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t5-p1', 'lt-t5', 1, 'You will hear a man phoning a car hire company.', 'Agent: Good morning, Coastline Car Hire. How can I help? Man: Hi, I''d like to hire a car for a week in September. Agent: Certainly. Where will you be collecting it? We have offices at the airport and in the city centre. Man: The airport, please, because I''m flying in. Agent: And the date? Man: The eleventh of September. I land at about two in the afternoon. Agent: What kind of car are you looking for? Man: Something small would be fine, but there''ll be four of us with luggage, so maybe a medium one. Actually, let''s say an estate car, for the extra space. Agent: An estate. That''s sixty-two pounds a day. Man: That''s fine. Agent: Would you like to add a second driver? Man: Yes, my wife will drive too. Agent: That''s an extra five pounds a day. Can I have her name? Man: Ingrid Hollis. Agent: Do you need any extras, such as a child seat or satellite navigation? Man: No child seat, but satellite navigation would be useful. Agent: It''s included free with estate cars. Man: Oh, good. Agent: The car will come with a full tank, and you need to return it full. Man: Understood. Agent: And for the insurance, you''ll need to show your driving licence and a credit card. Man: No problem.', 30) ON CONFLICT (id) DO NOTHING;
