INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t5-p2', 'lt-t5', 2, 'You will hear a guide welcoming visitors to a botanical garden.', 'Guide: Good morning and welcome to Lindley Botanical Gardens. The gardens were founded in 1846 by a doctor who wanted to grow plants for medicine, and that collection of medicinal plants is still here today, near the main gate. Today the gardens cover sixteen hectares and contain over twelve thousand species. Our most famous plant is the giant water lily in the tropical house. Its leaves can grow up to three metres across, and they''re strong enough to support the weight of a small child, although of course we don''t allow that. If you''re interested in birds, the best place to see them is the lake at the northern end, where herons often nest. The gardens rely heavily on volunteers, who do most of the weeding and guide many of the tours. A few practical points. You''re welcome to take photographs anywhere except in the orchid house, because the flash damages the flowers. The café serves hot food until two o''clock, and after that only sandwiches and cakes. There are free guided walks every day at eleven. And if you''d like to support us, the best way is to become a Friend of the Gardens, which gives you free entry all year for a small annual fee. Before you go, do visit the shop, which sells seeds collected here in the gardens.', 30) ON CONFLICT (id) DO NOTHING;
