INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t6-p1', 'lt-t6', 1, 'You will hear a father phoning an arts centre to book a summer camp for his son.', 'Receptionist: Good morning, Kingsway Arts Centre. Father: Hello, I''m calling about the summer art camp for children. I''d like to book a place for my son. Receptionist: Of course. How old is he? Father: He''s eight. Receptionist: Then he''d be in the junior group, which is for ages seven to ten. Father: Good. What does the camp involve? Receptionist: Each week has a theme. The first week is painting, the second is sculpture, and the third is animation. Father: He''s mad about cartoons, so the third week, please. Receptionist: Animation, then. That week runs from the twenty-first to the twenty-fifth of July, from nine until three each day. Father: What does it cost? Receptionist: It''s a hundred and ten pounds for the week, but there''s a ten per cent discount if you book before the end of May. Father: Great, I''ll book now. Does he need to bring anything? Receptionist: Just a packed lunch and an old shirt to protect his clothes. Father: And who''s the teacher? Receptionist: The animation week is taught by Anna Friedman. She''s worked for a film studio. Father: Wonderful. Receptionist: Can I take your son''s name? Father: It''s Leo Barrington. Receptionist: And is there anything we should know about his health? Father: He has asthma, so he carries an inhaler. Receptionist: Thanks, I''ll note that. Finally, how did you hear about us? Father: From a poster at his school.', 30) ON CONFLICT (id) DO NOTHING;
