INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t6-p2', 'lt-t6', 2, 'You will hear a librarian giving new students an introduction to the university library.', 'Librarian: Hello, everyone. Welcome to Westmoor University Library. I''m going to give you a quick introduction before you explore on your own. The library is open twenty-four hours a day during term, but outside term time it closes at nine in the evening. You''ll need your student card to get in after six. You can borrow up to fifteen books at a time. Most books can be kept for three weeks, but books in high demand, which have a red label, can only be borrowed for two days. If you want a book that''s out on loan, you can reserve it online, and we''ll email you when it comes back. Please don''t eat anywhere except in the café, although you can bring drinks in bottles with lids. Many students ask about printing. Printing is paid for with your student card, and it''s cheaper in black and white. Now, have a look at the plan. You come in at the main entrance, at the bottom of the plan, and the help desk is straight ahead on the right. The group study area is the room on the east side just north of the cross corridor. You can book it for up to three hours. The printing room is the room in the south-west corner, on your left as you come in. The silent reading room is the room in the north-east corner, as far as possible from the entrance. The newspaper archive is the room on the west side just north of the cross corridor, opposite the group study area. And finally, the café is the room in the south-east corner, so you can get a coffee as soon as you arrive.', 30) ON CONFLICT (id) DO NOTHING;
