INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t7-p1', 'lt-t7', 1, 'You will hear a student registering at a language school.', 'Secretary: Welcome to Lindon Language School. Are you here to register? Student: Yes, for the English course. Secretary: Lovely. Can I have your first name? Student: It''s Yusuf. Secretary: And your family name? Student: Demir. D, E, M, I, R. Secretary: Thank you. Where are you from? Student: Turkey, from Izmir. Secretary: And what''s your date of birth? Student: The fourth of March, 1999. Secretary: What''s your current level of English? Student: I think intermediate. My teacher at home said upper intermediate, but I''m not so confident. Secretary: You''ll take a placement test anyway. Which course are you interested in? We have general English, business English and exam preparation. Student: Exam preparation. I need a good score for university. Secretary: Morning or afternoon classes? Student: Mornings, because I work in a hotel in the afternoons. Secretary: How long would you like to study? Student: Twelve weeks. Secretary: Where are you staying? Student: With a host family in Clifton. Secretary: And who should we contact in an emergency? Student: My cousin, Selin. Secretary: Great. Finally, what are your interests? We organise social activities. Student: I love photography. Secretary: Then you''ll enjoy our photography club on Wednesdays.', 30) ON CONFLICT (id) DO NOTHING;
