INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t8-p1', 'lt-t8', 1, 'You will hear a woman phoning a company to hire camping equipment.', 'Assistant: Outdoor Hire, can I help you? Woman: Yes, I''m going camping with some friends and we''d like to hire some equipment. Assistant: Sure. When''s the trip? Woman: The last weekend in August, Friday to Monday. Assistant: So three nights. What do you need? Woman: A tent for four people, and four sleeping bags. Assistant: We have a four-person tent, but if you want more room, the six-person tent is only a little more. Woman: The four-person one is fine; we don''t have much space in the car. Assistant: OK. The tent is twenty pounds a night and sleeping bags are six pounds each per night. Woman: Do you have cooking equipment? Assistant: Yes, a camping stove and pans, for fifteen pounds for the whole trip. Woman: We''ll take those. Assistant: Would you like us to deliver? It''s free if you live within ten miles. Woman: We live in Hartley, which is about eight miles away. Assistant: Then delivery is free. We''ll deliver on Thursday evening. We need a deposit of fifty pounds. Woman: Can I pay by bank transfer? Assistant: Of course. Please check the tent when it arrives, and make sure it''s dry before you return it; if it''s returned wet, there''s a cleaning charge.', 30) ON CONFLICT (id) DO NOTHING;
