INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t9-p1', 'lt-t9', 1, 'You will hear a man phoning a hotel to book a room for his family.', 'Receptionist: Good evening, Seacliff Hotel. How can I help? Man: Hello, I''d like to book a room for my family in October. Receptionist: Certainly. What dates? Man: From the nineteenth to the twenty-second. Receptionist: Three nights. How many guests? Man: Two adults and two children. Receptionist: We have family rooms with a double bed and two single beds. Would you like a sea view? Man: How much extra is that? Receptionist: Fifteen pounds a night. Man: Yes, let''s have the sea view. Receptionist: The family room with a sea view is a hundred and forty pounds a night, including breakfast. Man: That''s fine. Do you have parking? Receptionist: Yes, it''s free, but spaces can''t be reserved. Man: OK. My younger son is allergic to feathers. Receptionist: I''ll make sure the room has non-feather pillows. Man: Thank you. Is there anything for children to do? Receptionist: There''s an indoor pool, which is open until eight in the evening, and a games room. Man: Great. Could I book dinner for our first night? Receptionist: Of course. At what time? Man: Half past six, please; the children eat early. Receptionist: And your name, please? Man: Martin Kowalczyk. K, O, W, A, L, C, Z, Y, K. Receptionist: Thank you. We''ll need a card to guarantee the booking.', 30) ON CONFLICT (id) DO NOTHING;
