INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t9-p2', 'lt-t9', 2, 'You will hear a guide talking to visitors at a castle heritage centre.', 'Guide: Welcome to Greystone Heritage Centre, which tells the story of Greystone Castle. The castle itself was first built in the twelfth century, but what you see today dates mostly from the fifteenth, when it was rebuilt after a fire. For three hundred years it belonged to the Ashford family, who sold it to the state in 1952. Before you set off, a few things to know. The castle walls are open to visitors, but the north tower is closed at the moment for repairs to the stairs. Our audio guides are free, and they''re available in nine languages. On Saturdays, there''s a special event: actors in costume show what daily life was like in the castle. If you''re short of time, the thing I''d recommend most is the view from the east wall, over the river. Now, have a look at the plan of the heritage centre. The main entrance is at the bottom. If you haven''t bought your ticket online, you''ll need to go to the ticket office, the first room on your right as you come in. The armour gallery is the room on your right just after the cross corridor, next to the chapel. Our newest display is the kitchen exhibition, the last room on your left, at the far end, opposite the chapel. The toilets are in the first room on your left as you come in. And families should head for the children''s activity room, the room on your right just before the cross corridor, which is opposite the shop.', 30) ON CONFLICT (id) DO NOTHING;
