INSERT INTO listening_parts (id, test_id, part_no, setting, script, reading_seconds) VALUES ('lt-t10-p1', 'lt-t10', 1, 'You will hear a woman phoning a trampoline park to book a birthday party.', 'Assistant: Jump Zone, Kelly speaking. Mother: Hi, I''d like to book a birthday party for my daughter. Assistant: Lovely. How old will she be? Mother: Seven. Assistant: And what date? Mother: Saturday the ninth of November. Assistant: Let me check. The morning is booked, but we have a slot at two o''clock. Mother: Two is fine. Assistant: How many children? Mother: About fifteen. Assistant: Our standard package covers up to twenty children and costs a hundred and eighty pounds. That includes an hour of jumping and forty-five minutes in the party room. Mother: What about food? Assistant: We provide pizza and drinks. If you want a cake, you''ll need to bring your own. Mother: That''s fine. Do the children need anything? Assistant: They must wear our special grip socks, which cost two pounds a pair, and every child needs a form signed by a parent. Mother: Can parents send the forms in advance? Assistant: Yes, they can complete them on our website. Mother: Great. Assistant: Could I have your name? Mother: Alison Greaves. G, R, E, A, V, E, S. Assistant: We''ll need a deposit of fifty pounds to confirm.', 30) ON CONFLICT (id) DO NOTHING;
